module tb_conv_bias_preload_ddr;
    logic clk=0,rst_n=0,start,rv,rr,rdv,rdr,av,ar,busy,done,error; logic [31:0] ra; logic [7:0] rd,aa; logic signed [31:0] ad; logic [31:0] mem[0:3]; logic signed [31:0] acc[0:255]; integer errors,cycles,start_cycle,first_request_cycle;
    always #5 clk=~clk;
    conv_bias_preload_ddr dut(.clk(clk),.rst_n(rst_n),.start(start),.bias_base_addr(0),.channel_offset(1),.tile_rows(2),.tile_cols(3),.busy(busy),.done(done),.error(error),.read_req_valid(rv),.read_req_ready(rr),.read_req_addr(ra),.read_data_valid(rdv),.read_data_ready(rdr),.read_data(rd),.accum_valid(av),.accum_ready(ar),.accum_addr(aa),.accum_data(ad));
    always @(posedge clk) begin cycles<=cycles+1;if(start)begin start_cycle<=cycles;first_request_cycle<=-1;end if(rv&&rr&&first_request_cycle<0)first_request_cycle<=cycles;rr<=1; ar<=1; rdv<=rv; rd<=mem[ra>>2][(ra[1:0])*8 +: 8]; if(av&&ar) acc[aa]<=ad; end
    initial begin errors=0;cycles=0;start_cycle=-1;first_request_cycle=-1;start=0;rr=0;ar=0;rdv=0;rd=0;mem[1]=-7;mem[2]=13;mem[3]=-21;for(int i=0;i<256;i++)acc[i]=0;repeat(3)@(posedge clk);rst_n=1;@(posedge clk);start=1;@(posedge clk);start=0;wait(done);#1;if(first_request_cycle-start_cycle<1)$fatal(1,"Bias preload pipeline latency was %0d cycles, expected at least 1",first_request_cycle-start_cycle);if(acc[0]!=-7||acc[16]!=-7||acc[1]!=13||acc[17]!=13||acc[2]!=-21||acc[18]!=-21)errors++;if(error||errors)$fatal(1,"bias preload failed");$display("Conv2D bias accumulator preload golden trace passed");$finish;end
endmodule
